export function diningRoom(s,st,{E,esc,savedShopButton}){
 const history=s.diningVisits.filter(v=>v.store===st.id).slice(-3).reverse();
 return `<div class="modal-body dining-room"><div class="dining-intro"><span class="eyebrow">A LITTLE BREAK BETWEEN SHOPS</span><h3>Take a seat. Take your time.</h3><p>An original Mallside game menu, shared by dining locations. These meals and game prices do not describe this restaurant’s real menu.</p>${savedShopButton(s,st.id,{esc})}</div><div class="dining-menu">${E.diningMenu(st).map(f=>`<article><span class="meal-symbol" aria-hidden="true">${({coffee:'☕',snack:'◒',sandwich:'▱',bowl:'◡',icecream:'♧'})[f.id]}</span><h3>${esc(f.name)}</h3><strong>${E.money(f.price)}</strong><p>${f.minutes} game min · +${f.hunger} fullness · +${f.energy} stamina</p><button class="button orange wide" data-action="dining-review" data-id="${f.id}">Review this meal</button></article>`).join('')}</div><p class="hint">Review first. Game money is spent only when you reach the dining seat. Stop walking or exit to cancel.</p>${history.length?`<details><summary>Your recent breaks here</summary>${history.map(v=>`<p>Day ${v.day} · ${esc(E.FOOD.find(f=>f.id===v.meal).name)} · ${E.money(v.paid)}</p>`).join('')}</details>`:''}<div class="service-links"><button class="button secondary" data-action="dining-collection">${st.count?'Browse real products':'Collection guide'}</button><button class="button secondary" data-action="dining-returns">Receipts & returns</button></div></div>`;
}
export function sculptureAlcove(s,{E,esc}){
 const note=s.artNotes.find(n=>n.mallId===s.mallId&&n.floor===(s.floor||0)),done=note?.day===s.day;
 return `<div class="modal-body sculpture-alcove"><div class="sculpture-illustration" aria-hidden="true"><i></i><i></i></div><span class="eyebrow">ORIGINAL MALLSIDE SCULPTURE · TWO LINES</span><h3>A small pause in a quiet court.</h3><p>Walk around the looping forms, then choose a detail for your sketchbook.</p><div class="commons-pages">${E.ART_DETAILS.map(d=>`<article><h3>${d.name}</h3><p>${d.text}</p><button class="button secondary" data-action="art-sketch" data-id="${d.id}" ${done?'disabled':''}>${note?.detail===d.id?'Sketch this again':'Sketch this detail'}</button></article>`).join('')}</div><p class="hint">${done?'Sketch saved here today. Explore freely; return tomorrow for another note.':'Free · 3 game min · +4 stamina. First sketch on this floor: 5 XP.'}</p><button class="button secondary" data-action="art-notebook">My sketchbook · ${s.artNotes.length} floors</button><button class="text-button" data-action="close">Back to the mall</button></div>`;
}
export function artNotebook(s,{E,esc}){return `<div class="modal-body"><p>Your sketches of the original Two Lines sculptures, one in every mall floor’s quieter courts.</p>${s.artNotes.length?s.artNotes.map(n=>`<article class="art-note"><small>Day ${n.day} · ${esc(E.mallById(n.mallId).name)} · ${esc(E.planFor({mallId:n.mallId}).levels[n.floor])}</small><h3>${E.ART_DETAILS.find(d=>d.id===n.detail).name}</h3><p>${E.ART_DETAILS.find(d=>d.id===n.detail).text}</p></article>`).join(''):'<p>No sketches yet. Find Sculpture alcove in Map & things to do.</p>'}<button class="button orange wide" data-action="center-map">Find a sculpture on the map</button></div>`;}
